/// The cargo registry name for a logical registry key (`cratesIo` is cargo's `crates-io`).
pub fn cargo_registry_name(key: &RegistryKey) -> &str {
    if key.as_str() == RegistryKey::CRATES_IO {
        "crates-io"
    } else {
        key.as_str()
    }
